<script setup lang="ts">
import {onBeforeUnmount,ref} from 'vue'
import {invoke} from '@tauri-apps/api/core'
import {useI18n} from '@/lib/i18n'
const {pick}=useI18n(),routeConfirmed=ref(false),synthetic=ref(false),token=ref(''),payload=ref(''),busy=ref(false),error=ref(''),result=ref<{status:string;message:string;response:string}|null>(null)
onBeforeUnmount(()=>{token.value='';payload.value='';result.value=null})
async function validate(){if(!routeConfirmed.value||!synthetic.value||!token.value||busy.value)return;busy.value=true;error.value='';result.value=null;try{result.value=await invoke('validate_fbr_sandbox',{request:{confirmedDiRoute:routeConfirmed.value,syntheticData:synthetic.value,token:token.value,payload:payload.value}})}catch(e){error.value=String(e)}finally{token.value='';busy.value=false}}
</script>
<template><div class="tool-terminal documents-terminal"><header class="tool-header"><div><h1>{{pick('FBR DI Sandbox Check','FBR DI سینڈ باکس جانچ')}}</h1><p>{{pick('Integration spike · validation only · production is not connected','انضمام کی ابتدائی جانچ · صرف تصدیق · پروڈکشن سے منسلک نہیں')}}</p></div></header><p class="commercial-hint">{{pick('The shop’s onboarding route is not yet confirmed. This connector supports the official DI sandbox validation endpoint only; it is not a Tier-1 POS adapter. Confirm your portal route, assigned business sector/scenarios and sandbox token first. No live invoice or compliance claim follows from this screen.','دکان کے انضمام کا راستہ ابھی تصدیق شدہ نہیں۔ یہ صرف سرکاری DI سینڈ باکس جانچ سے منسلک ہے؛ Tier-1 POS اڈاپٹر نہیں۔ پہلے پورٹل کا راستہ، کاروباری شعبہ / منظرنامے اور سینڈ باکس ٹوکن تصدیق کریں۔ یہ اسکرین حقیقی بل یا تعمیل کی سند نہیں بناتی۔')}}</p>
<p class="commercial-hint"><a href="https://fbr.gov.pk/di-technical-assistance/173967/173970" target="_blank" rel="noreferrer">{{pick('Official FBR technical documentation','سرکاری FBR تکنیکی دستاویزات')}}</a> · {{pick('Uses the validate sandbox method, not invoice submission. Existing offline sales/stock are never sent automatically. Use only synthetic data copied from your assigned sandbox scenario; review every tax/HS/UOM field.','سینڈ باکس کی جانچ استعمال ہوتی ہے، بل جمع نہیں ہوتا۔ موجودہ آف لائن فروخت / اسٹاک خودکار نہیں بھیجا جاتا۔ صرف اپنے مقررہ سینڈ باکس منظرنامے کا مصنوعی ڈیٹا استعمال کریں؛ ہر ٹیکس / HS / UOM کالم کا جائزہ لیں۔')}}</p>
<form class="catalog-sandbox-form" @submit.prevent="validate"><label><input v-model="routeConfirmed" type="checkbox" :disabled="busy"/> {{pick('My onboarding portal confirms the FBR DI sandbox route.','میرا پورٹل FBR DI سینڈ باکس کے راستے کی تصدیق کرتا ہے۔')}}</label><label><input v-model="synthetic" type="checkbox" :disabled="busy"/> {{pick('This payload contains synthetic sandbox data and I authorize sending it to FBR for validation.','یہ مصنوعی سینڈ باکس ڈیٹا ہے اور میں اسے جانچ کے لیے FBR بھیجنے کی اجازت دیتا ہوں۔')}}</label><label>{{pick('Sandbox bearer token (memory only)','سینڈ باکس ٹوکن (صرف عارضی میموری)')}}<input v-model="token" type="password" autocomplete="off" maxlength="4096" :disabled="busy" required/></label><label>{{pick('Assigned sandbox invoice JSON','مقررہ سینڈ باکس بل JSON')}}<textarea v-model="payload" rows="12" maxlength="256000" :disabled="busy" required spellcheck="false"/></label><p>{{pick('The token is cleared after every attempt and when leaving this workspace. Do not paste production credentials or real patient/customer records.','ٹوکن ہر کوشش اور اسکرین چھوڑنے پر خالی ہو جاتا ہے۔ پروڈکشن کی اسناد یا حقیقی مریض / گاہک کا ریکارڈ نہ چسپاں کریں۔')}}</p><button class="bg-primary" :disabled="busy||!routeConfirmed||!synthetic||!token">{{pick('Validate in DI sandbox','DI سینڈ باکس میں جانچیں')}}</button></form><p v-if="error" role="alert" class="commercial-error">{{error}}</p><section v-if="result" class="commercial-hint"><strong>{{result.status}}</strong><p>{{result.message}}</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">{{result.response}}</pre></section></div></template>
<style scoped>.catalog-sandbox-form{display:grid;gap:.8rem;padding:1rem;overflow:auto;min-height:0}.catalog-sandbox-form label{display:grid;gap:.3rem}.catalog-sandbox-form label:has(input[type=checkbox]){display:block}.catalog-sandbox-form textarea{font:12px monospace;min-height:180px}.catalog-sandbox-form button{justify-self:start}</style>
